"""从已有练习页和人工核对的课程内容生成静态章节数据。只用标准库。"""
from pathlib import Path
import re, json, html, shutil

ROOT = Path(__file__).resolve().parent
DIST = ROOT / 'dist'
DIST.mkdir(exist_ok=True)
(DIST / 'courseware').mkdir(exist_ok=True)

def paragraphs(text):
    return ''.join('<p>'+html.escape(p).replace('\n','<br>')+'</p>' for p in text.split('\n\n'))

chapters = []
def chapter(number, title, description, source_names, notes, coverage='课件与章节练习'):
    sources=[]
    for i, name in enumerate(source_names):
        target=f'chapter-{number}-{i+1}.pdf'
        shutil.copyfile(ROOT.parent/name, DIST/'courseware'/target)
        sources.append({'title':name,'url':'courseware/'+target})
    c={'id':str(number),'number':number,'title':title,'description':description,'coverage':coverage,
       'sources':sources,'knowledge':[{'title':a,'body':b,'source':s} for a,b,s in notes], 'questions':[]}
    chapters.append(c)
    return c

def q(c, code, kind, stem, options, correct, explanation, topic='', origin='学习指导书选题', source='', level='标准'):
    assert kind in ['判断','单选','多选','简答','业务计算']
    if kind=='判断': options=['正确','错误']; correct=[0 if correct else 1]
    elif isinstance(correct,int): correct=[correct]
    c['questions'].append({'id':code,'type':kind,'stem':stem,'options':options,'correct':correct,
      'explanation':paragraphs(explanation),'topic':topic,'origin':origin,'source':source or (f'学习指导书第{c["id"]}章 · 用户提供题图' if origin=='学习指导书选题' else f'依据第{c["id"]}章课件自编'), 'level':level})

