selfq(c3,9,'业务计算','企业购入并验收入库原材料10 000元，货款尚未支付。本题不考虑增值税。编制会计分录。',[],None,'原材料增加，记借方；应付账款增加，记贷方。\n借：原材料 10 000\n　贷：应付账款 10 000','分录')
selfq(c3,10,'业务计算','企业用银行存款偿还前欠供应商货款6 000元。编制会计分录。',[],None,'应付账款减少，记借方；银行存款减少，记贷方。\n借：应付账款 6 000\n　贷：银行存款 6 000\n归还本金不是费用。','分录')
selfq(c3,11,'多选','下列错误可能无法通过借贷试算平衡发现的有（　）。',['整笔业务漏记','一笔分录借方多记100元、贷方未多记','整笔业务重复登记','把正确借方科目记成另一个借方科目，金额正确','只登记一笔分录的借方'],[0,2,3],'A、C对借贷双方的影响对称，D科目错但借贷仍相等。B、E会直接导致借贷不平衡。试算平衡检查数量关系，不保证业务完整性和科目正确。','试算平衡','综合')
selfq(c3,12,'判断','只要试算平衡表借贷合计相等，就能证明所有账务处理正确。',[],False,'相等只是必要检查结果，不能证明完全正确。整笔漏记、重记或某些科目错误仍可能平衡。','试算平衡')
selfq(c3,13,'业务计算','银行存款期初余额20 000元。本期收到股东投资30 000元，支付原欠货款8 000元，支付行政办公费2 000元。编制三笔分录，并求银行存款期末余额。不考虑税费。',[],None,'①借：银行存款 30 000；贷：实收资本 30 000。\n②借：应付账款 8 000；贷：银行存款 8 000。\n③借：管理费用 2 000；贷：银行存款 2 000。\n银行存款期末余额＝20 000＋30 000－8 000－2 000＝40 000元，在借方。\n投资不是收入，还债本金不是费用。','分录与余额','综合')
selfq(c3,14,'简答','写出借贷记账法的记账规则，并说明为什么“借方”不能直接理解为“收入现金”。',[],None,'规则：有借必有贷，借贷必相等。\n借方是账户左侧的记账符号，不是现金流入的同义词。例如借记应付账款表示负债减少；购入材料未付款，也会借记原材料但没有现金流入。','方法解释','综合')

c4=chapter(4,'企业主要经济业务的核算','沿着筹资、采购、生产、销售、利润分配，练习完整业务处理。',['第04周_第4章_企业主要经济业务的核算_上(1).pdf','第05周_第4章_企业主要经济业务的核算_下.pdf'],[
 ('先看资金在哪一阶段','筹资取得资金；供应取得设备材料；生产归集产品成本；销售确认收入并结转成本；期末计算和分配利润。每笔分录先定位业务阶段。','第4章上第8页、下第41页'),
 ('投资与借款','接受投资通常借记银行存款等、贷记实收资本；超过资本份额的部分按题意记资本公积。取得借款是负债增加，不是营业收入。','第4章上第10—19页'),
 ('采购与增值税','题目满足一般纳税人可抵扣条件时，材料成本与进项税额分开；可抵扣进项不计入材料成本。尚未入库可记在途物资，验收入库再转原材料。','第4章上供应阶段部分'),
 ('生产成本归集','直接材料、直接人工直接计入产品生产成本。车间一般耗用及车间管理费用先归集制造费用，再按合理标准分配。行政管理费用不能混入产品成本。','第4章下第6—14页'),
 ('销售有两条线','确认销售收入及销项税额是一笔；结转已售商品成本是另一笔。收到的含税价款不全是收入，销售收入也不全是利润。','第4章下第16—23页'),
 ('期末结转','收入类结转到本年利润贷方，费用类结转到本年利润借方；计入所得税费用后形成净利润。年末再把本年利润转入利润分配—未分配利润。','第4章下第31—34页'),
 ('利润分配','提取盈余公积是所有者权益内部变化，不是费用。宣告向股东分配利润形成应付利润等负债；实际支付时再减少银行存款。','第4章下第35—39页'),
 ('课件口径提醒','课件示例包含16%等旧税率，本网站新编税额题一律在题干给定税率，只用于练习计算。下册第19页例4-24的销项税分录数字与题干有20元差异，应按题干金额267 520元核对。','第4章上第22页、下第19页')])
selfq(c4,1,'业务计算','企业收到股东投入资金200 000元，其中150 000元计入实收资本，其余为资本溢价。编制分录。',[],None,'资本溢价＝200 000－150 000＝50 000元。\n借：银行存款 200 000\n　贷：实收资本 150 000\n　　　资本公积—资本溢价 50 000\n不得把溢价当营业收入。','筹资')
selfq(c4,2,'业务计算','企业取得期限6个月的银行借款120 000元，存入银行。年利率6%，按月计提利息。本月为完整一个月，利息尚未支付且不满足资本化条件。编制取得借款及计提本月利息的分录。',[],None,'取得：借：银行存款 120 000；贷：短期借款 120 000。\n月利息＝120 000×6%÷12＝600元。\n计提：借：财务费用 600；贷：应付利息 600。\n取得本金和确认利息是两件事。','筹资','综合')
selfq(c4,3,'业务计算','一般纳税人购入材料，题定不含税价10 000元、增值税率13%，取得可抵扣专用发票，材料已验收入库，价税全部银行支付。编制分录。',[],None,'进项税额＝10 000×13%＝1 300元；付款总额11 300元。\n借：原材料 10 000\n　　应交税费—应交增值税（进项税额）1 300\n　贷：银行存款 11 300\n本题税率由题目给定，不用于断言课件历史例题税率。','采购')
selfq(c4,4,'业务计算','企业按实际成本法核算材料。购入材料12 000元，货款未付、材料未到。本题忽略增值税。随后材料验收入库。分别编制两时点分录。',[],None,'购入未到：借：在途物资 12 000；贷：应付账款 12 000。\n验收入库：借：原材料 12 000；贷：在途物资 12 000。\n材料入库不代表已经付款，应付账款仍存在。','采购')
selfq(c4,5,'多选','一般纳税人购料，下列哪些支出按题目条件可计入材料采购成本（　）？',['材料不含税买价','取得合规凭证且允许抵扣的进项税额','直接归属于本批材料的合理运输费（不含可抵扣税）','采购人员日常行政办公费用'],[0,2],'合理且直接归属于材料的买价和运输费计入采购成本。允许抵扣的进项税额单独核算；日常行政办公费用不直接计入该批材料采购成本。','采购')
selfq(c4,6,'业务计算','仓库发出材料：甲产品直接耗用8 000元，车间一般耗用1 000元，行政管理部门耗用500元。编制分录。',[],None,'借：生产成本—甲产品 8 000\n　　制造费用 1 000\n　　管理费用 500\n　贷：原材料 9 500\n先看材料由谁使用，不能全部记生产成本。','生产')
selfq(c4,7,'业务计算','本月应付工资：甲产品生产工人6 000元，车间管理人员1 000元，行政人员2 000元。先分配工资费用，后用银行存款发放。编制两笔分录。',[],None,'分配：借：生产成本—甲产品 6 000；制造费用 1 000；管理费用 2 000；贷：应付职工薪酬 9 000。\n发放：借：应付职工薪酬 9 000；贷：银行存款 9 000。\n分配体现费用成本归属，发放冲减应付义务，不能重复记费用。','生产','综合')
selfq(c4,8,'业务计算','企业计提本月折旧：生产车间设备1 200元，行政办公设备300元。编制分录。',[],None,'借：制造费用 1 200\n　　管理费用 300\n　贷：累计折旧 1 500\n贷方通常记累计折旧，不直接贷固定资产。费用归属按资产用途判断。','生产')
selfq(c4,9,'业务计算','本月制造费用9 000元，按生产工人工资比例分配。甲产品工资6 000元，乙产品工资3 000元。计算分配额并编制分录。',[],None,'分配率＝9 000÷（6 000＋3 000）＝1。\n甲分配6 000元，乙分配3 000元。\n借：生产成本—甲产品 6 000\n　　生产成本—乙产品 3 000\n　贷：制造费用 9 000\n两产品承担额合计必须等于待分配金额。','生产','综合')
selfq(c4,10,'业务计算','某产品月初在产品成本2 000元，本月归集生产成本18 000元，月末在产品成本3 000元。求本月完工产品成本，并编制完工入库分录。',[],None,'完工成本＝月初在产品＋本月生产费用－月末在产品\n＝2 000＋18 000－3 000＝17 000元。\n借：库存商品 17 000\n　贷：生产成本 17 000\n不能把本月费用18 000元直接当完工成本。','生产','综合')
selfq(c4,11,'业务计算','一般纳税人销售商品，题定不含税售价20 000元，增值税率13%，收款存入银行。已售商品成本12 000元。收入确认条件已满足。编制收入与成本两笔分录。',[],None,'销项税＝20 000×13%＝2 600元；收款22 600元。\n①借：银行存款 22 600；贷：主营业务收入 20 000；应交税费—应交增值税（销项税额）2 600。\n②借：主营业务成本 12 000；贷：库存商品 12 000。\n暂不考虑其他项目，销售毛利8 000元，不是20 000元，也不是22 600元。','销售','综合')
selfq(c4,12,'判断','赊销商品没有收到钱，因此即使已经满足收入确认条件，也不能确认收入。',[],False,'权责发生制不以收款为唯一标准。满足条件时确认应收账款和收入；相关增值税按题目要求另行处理。','销售')
selfq(c4,13,'业务计算','按课件预收账款口径，企业预收货款8 000元存入银行，尚未履行交货义务。本题不考虑税费。编制分录，并说明是否确认收入。',[],None,'借：银行存款 8 000\n　贷：预收账款 8 000\n暂不确认收入，因为尚未满足题设收入确认条件。这里沿用第9版课件预收账款科目，不混入其他版本题号或科目要求。','销售')
selfq(c4,14,'业务计算','期末主营业务收入100 000元、其他业务收入5 000元；主营业务成本60 000元、管理费用10 000元。暂不考虑其他收支和所得税。编制损益结转分录并求结转后的本年利润余额。',[],None,'收入结转：借：主营业务收入100 000；其他业务收入5 000；贷：本年利润105 000。\n成本费用结转：借：本年利润70 000；贷：主营业务成本60 000；管理费用10 000。\n本年利润贷方余额＝105 000－70 000＝35 000元。','利润','综合')
selfq(c4,15,'业务计算','企业利润总额40 000元。题目给定所得税费用按利润总额的25%计算，无纳税调整等其他因素。计算所得税费用和净利润，并写计提所得税分录。',[],None,'所得税费用＝40 000×25%＝10 000元。\n净利润＝40 000－10 000＝30 000元。\n借：所得税费用10 000；贷：应交税费—应交所得税10 000。\n实际纳税计算可能更复杂，本题仅按给定条件。','利润')
selfq(c4,16,'业务计算','年末本年利润账户结转前为贷方余额30 000元。编制将其转入未分配利润的分录。',[],None,'借：本年利润 30 000\n　贷：利润分配—未分配利润 30 000\n转出后本年利润余额为零。若为亏损，结转方向相反。','利润')
selfq(c4,17,'业务计算','按题目给定要求，从净利润中提取盈余公积3 000元。编制分录，并判断所有者权益总额是否变化。',[],None,'借：利润分配—提取盈余公积 3 000\n　贷：盈余公积 3 000\n属于所有者权益内部调整，总额不变，不记管理费用。','利润分配')
selfq(c4,18,'业务计算','股东会决议分配现金利润8 000元，稍后从银行支付。沿用课件“应付利润”科目，分别编制宣告与支付分录。',[],None,'宣告：借：利润分配—应付利润 8 000；贷：应付利润 8 000。\n支付：借：应付利润 8 000；贷：银行存款 8 000。\n宣告时权益减少、负债增加；付款时资产和负债减少。分红不是经营费用。','利润分配','综合')

c5=chapter(5,'账户的分类','用不同标准看同一账户，练习备抵账户、实虚账户与平行登记。',['week06_第5章_账户的分类.pdf'],[
 ('分类标准不能混用','按经济内容、按用途结构、按详细程度、按期末是否有余额，都是不同角度。一个账户可以同时属于多个分类。','第5章课件第8—18页'),
 ('总账与明细账','总账提供总括信息，统驭所属明细账；明细账提供详细信息，对总账起补充说明作用。两者反映同类经济内容。','第5章课件第16、28页'),
 ('平行登记','依据相同、方向一致、金额相等、期间相同。总账金额等于有关明细账金额的合计，不是每个明细账都复制总账金额。课件“同时登记”按同一期间理解。','第5章课件第28—39页'),
 ('备抵账户','累计折旧、坏账准备等用来抵减对应资产账面余额。累计折旧通常贷方有余额，但属于资产的备抵，不能仅凭贷方余额判成负债。','第5章课件第22—24页'),
 ('用途和结构','盘存账户反映财产物资，结算账户反映债权债务；制造费用属于集合分配账户，生产成本属于成本计算账户。','第5章课件第17—21页'),
 ('实账户与虚账户','本课件把期末有结转余额的资产负债表账户称实账户；通过结账分录结平的损益账户称虚账户。不是说资产账户在任何情形都有非零余额。','第5章课件第25—26页'),
 ('课件计算核对','第36页应付账款总账示例：14 680－13 300＝1 380，和课件余额一致。其他示例若出现表内加总与文字不符，以逐项算式核对，不机械抄答案。','第5章课件第35—36页')])
selfq(c5,1,'单选','总分类账户与明细分类账户的关系，正确的是（　）。',['互不相关','总账统驭明细账，明细账补充说明总账','明细账必须逐个等于总账金额','只有明细账需要凭证'],1,'总账反映总括金额，明细账反映组成部分。相关明细账合计对应总账。','总账与明细')
selfq(c5,2,'多选','按用途和结构，下列属于盘存账户的有（　）。',['库存现金','原材料','固定资产','应付账款','实收资本'],[0,1,2],'现金、材料、固定资产反映财产物资；应付账款是债务结算账户，实收资本是资本账户。','账户分类')
selfq(c5,3,'单选','“累计折旧”在本章中主要属于（　）。',['负债账户，因为通常贷方有余额','固定资产的备抵账户','收入账户','债权结算账户'],1,'它抵减固定资产账面余额。正常余额在贷方，不改变其作为资产备抵账户的性质。','备抵账户')
selfq(c5,4,'业务计算','固定资产原价80 000元，累计折旧20 000元，固定资产减值准备5 000元。计算账面价值。',[],None,'账面价值＝原价－累计折旧－减值准备\n＝80 000－20 000－5 000＝55 000元。\n不要漏减减值准备，也不能把累计折旧加回。','备抵账户')
selfq(c5,5,'判断','只要账户期末为贷方余额，就一定属于负债账户。',[],False,'累计折旧通常是贷方余额，但属于资产备抵账户；实收资本也是贷方余额但属于权益。方向不能代替性质判断。','分类辨析')
selfq(c5,6,'多选','平行登记应注意的有（　）。',['依据相同','方向一致','金额合计相等','期间相同','必须在同一秒钟登记'],[0,1,2,3],'应在同一会计期间登记，不要求同一时刻。金额相等是总账与有关明细账合计对应。','平行登记')
selfq(c5,7,'业务计算','原材料总账期初借方余额10 000元，明细甲6 000元、乙4 000元。本期购入甲3 000元、乙2 000元；领用甲4 000元、乙1 000元。求两个明细与总账期末余额。',[],None,'甲＝6 000＋3 000－4 000＝5 000元。\n乙＝4 000＋2 000－1 000＝5 000元。\n总账＝10 000＋5 000－5 000＝10 000元。\n明细合计5 000＋5 000＝10 000，与总账相符，均为借方余额。','平行登记','综合')
selfq(c5,8,'单选','下列账户在本章中通常作为集合分配账户的是（　）。',['制造费用','库存现金','银行存款','实收资本'],0,'制造费用先归集，再按合理标准分配到有关生产成本。生产成本则是成本计算账户。','用途结构')
selfq(c5,9,'判断','主营业务收入属于虚账户，期末通过结转可以使其余额为零。',[],True,'收入转入本年利润后相应账户结平。不能据此说企业没有取得收入，发生额仍然存在。','实虚账户')
selfq(c5,10,'业务计算','某月向供应商甲赊购3 000元、乙赊购2 000元。随后偿还甲2 500元、乙1 500元，期初均不欠款。求应付账款总账及明细期末余额。',[],None,'甲贷方余额＝3 000－2 500＝500元。\n乙贷方余额＝2 000－1 500＝500元。\n总账贷方余额＝5 000－4 000＝1 000元。\n两明细贷方余额合计1 000元，与总账相符。','平行登记','综合')
selfq(c5,11,'简答','为什么“借贷平衡”不能替代“总账与明细账核对”？',[],None,'借贷平衡检验不同账户借贷合计关系。总账与明细核对检验总括记录与明细组成是否一致。例如总账正确、某供应商明细漏记，总账试算仍可能平衡，但明细不符。两个检查对象不同。','核对','综合')
selfq(c5,12,'多选','下列可作为资产备抵账户的有（　）。',['累计折旧','坏账准备','存货跌价准备','应付职工薪酬'],[0,1,2],'前三项分别抵减有关资产的账面余额；应付职工薪酬反映应付义务，是负债。','备抵账户')

c6=chapter(6,'会计凭证','从原始凭证到记账凭证，检查分类、凭证选择和审核更正。',['week07_第6章_会计凭证.pdf'],[
 ('两类凭证','原始凭证在业务发生或完成时取得或填制，用来证明业务；记账凭证据审核无误的原始凭证整理分类，确定科目、方向和金额。','第6章课件第7—8、15、43页'),
 ('原始凭证分类','按来源分外来、自制；按填制手续分一次、累计、汇总。发票通常外来；领料单自制；限额领料单是累计凭证，发料汇总表是汇总凭证。','第6章课件第15—25页'),
 ('记账凭证选择','收到现金或银行款项通常用收款凭证；付出用付款凭证；不涉及现金银行收付用转账凭证。现金与银行之间划转，只编付款凭证避免重复。','第6章课件记账凭证填制部分'),
 ('审核不是走形式','原始凭证检查真实、合法、合理、完整、正确、及时；记账凭证还要检查科目、借贷方向、金额、附件和手续。','第6章课件第26—28、41页'),
 ('更正对象要分清','原始凭证金额错误应由出具单位重开，不能直接划线修改金额。记账凭证未入账有误应重填；已入账要结合第7章更正。不能把账簿划线法套到所有凭证。','第6章课件原始凭证审核与填制要求，结合第7章'),
 ('凭证传递与保管','传递需明确程序、时间和责任；凭证要按规定整理、装订、归档并防止散失或抽换。出纳不得兼管会计档案。','第6章课件第45—48页')])
selfq(c6,1,'单选','供应商向本企业开具的购货发票，通常属于（　）。',['外来原始凭证','自制记账凭证','汇总记账凭证','转账凭证'],0,'发票由外单位在交易中开具，属于外来原始凭证。本企业据审核后的原始凭证填制记账凭证。','凭证分类')
selfq(c6,2,'多选','下列通常属于自制原始凭证的有（　）。',['本企业入库单','本企业领料单','供应商发票','本企业发料凭证汇总表'],[0,1,3],'入库单、领料单、发料汇总表由本企业内部填制；供应商开出的发票属于外来原始凭证。','凭证分类')
selfq(c6,3,'单选','在同一张凭证上，连续多次登记同类领料业务并控制限额，属于（　）。',['一次原始凭证','累计原始凭证','收款凭证','汇总记账凭证'],1,'限额领料单在一定期间同一张凭证上连续记录多次业务，是累计凭证。汇总凭证是汇总若干原始凭证后另行编制。','凭证分类')
selfq(c6,4,'单选','企业购入材料已入库，价款未支付，不考虑税费。采用专用记账凭证，应选择（　）。',['现金收款凭证','银行存款付款凭证','转账凭证','现金付款凭证'],2,'没有现金或银行存款收付，属于转账业务。借原材料、贷应付账款。','凭证选择')
selfq(c6,5,'单选','从银行提取现金备用，采用专用收付款凭证时通常填制（　）。',['现金收款凭证和银行付款凭证各一张','银行存款付款凭证','转账凭证','银行存款收款凭证'],1,'现金银行相互划转只编付款凭证。提现时银行存款减少，填银行存款付款凭证，同时据此登记现金收入，避免重复。','凭证选择')
selfq(c6,6,'判断','记账凭证填写正确就可以直接登账，不必审核。',[],False,'应先审核无误再据以登账。填写人员自认为正确，不能代替审核程序。','审核')
selfq(c6,7,'简答','一张外来原始凭证的金额有误，但其他内容正确。会计人员能否直接把错误金额划线改正？应怎样处理？',[],None,'不能直接划线修改原始凭证金额。应由出具单位重新开具。要区分原始凭证、记账凭证和账簿，各自的更正要求不同。','更正')
selfq(c6,8,'多选','审核记账凭证时应检查的有（　）。',['原始依据与业务是否真实','科目和借贷方向是否正确','金额是否正确','项目和有关手续是否齐全','只看借贷金额相等即可'],[0,1,2,3],'借贷相等只是检查之一。业务不真实、科目错误、附件和手续不全，即使借贷相等，也不能直接认为合格。','审核')
selfq(c6,9,'业务计算','企业用银行存款支付行政办公费1 200元，不考虑税费。写出专用凭证种类、贷方科目及分录。',[],None,'种类：银行存款付款凭证。贷方科目：银行存款。\n借：管理费用 1 200\n　贷：银行存款 1 200\n不能因为办公室使用就选转账凭证，实际有银行付款。','凭证填制')
selfq(c6,10,'判断','累计原始凭证与汇总原始凭证是同一种凭证，只是名称不同。',[],False,'累计是在同一张凭证上连续登记；汇总是根据若干同类原始凭证汇总编制。限额领料单与发料汇总表不能混同。','凭证分类')
selfq(c6,11,'简答','简述原始凭证与记账凭证在填制依据和作用上的区别。',[],None,'原始凭证据实际发生或完成的业务取得或填制，用于记录证明业务。记账凭证据审核无误的原始凭证等进行分类整理，确定科目、方向和金额，是登记账簿的重要直接依据。某些明细账可依审核后的原始凭证登记，不能绝对化。','凭证比较','综合')
selfq(c6,12,'简答','发现记账凭证有错时，为什么首先要确认“是否已经登记入账”？',[],None,'未入账时可重新填制正确凭证，避免错误进入账簿。已入账时只重填原凭证不能消除账簿的错误，需要按适用条件采用红字更正或补充登记等方法；若凭证无误、只是登账抄错，则另按第7章条件处理。','更正','综合')

c7=chapter(7,'会计账簿','分别判断账簿类别、登记依据、核对内容与错账更正条件。',['week08_第7章_会计账簿_上.pdf'],[
 ('账簿与账户','账簿是记录载体，账户是分类记录的内容与结构，二者不能画等号。凭证→账簿→报表构成基本信息流程。','第7章上课件第6—9页'),
 ('三套分类标准','按用途：序时、分类、备查；按外表：订本、活页、卡片；按账页格式：三栏、多栏、数量金额等。同一本账可以既是订本式又是三栏式。','第7章上课件第10—22页'),
 ('明细账格式选择','往来款项通常三栏式；费用成本分项通常多栏式；材料、商品需要数量和金额，通常数量金额式；固定资产通常设卡片。','第7章上课件第16—21、41—42页'),
 ('日记账登记','手工现金、银行日记账采用订本式；出纳按凭证逐日逐笔登记并结出余额。提现只编银行付款凭证，现金收入据该凭证登记。','第7章上课件第28—36页'),
 ('总账与明细平行登记','依据相同、方向一致、金额合计相等、期间相同。可编明细账户发生额和余额明细表核对。','学习指导书第7章题图；第5章课件补充'),
 ('对账分类','账证核对：账与凭证；账账核对：不同账簿；账实核对：现金实存、物资实存、银行对账单和债权债务对方记录。','学习指导书第7章题图；本次上半份课件未覆盖全部'),
 ('错账更正先查原因','凭证正确、结账前仅登账抄错：划线；凭证错且已入账，科目或方向错：红字冲销后重记；科目方向正确但多记：红字冲差额；少记：蓝字补差额。','学习指导书第7章题图；本次上半份课件未覆盖全部'),
 ('结账与更换','年结通常通栏双红线；总账、日记账和多数明细账通常每年更换，固定资产卡片等可连续使用。不能说所有账簿必须全部更换。','学习指导书第7章题图补充')],coverage='课件为上半部分；练习含已提供的第7章题册选题')
for code,stem,correct,ex in [
 ('T7-3','账户与账簿的联系十分密切，可以说账户等于账簿。',False,'账户用于分类记录特定事项，账簿是具体载体。两者有联系，但不是同一个概念。'),
 ('T7-7','备查账簿是对某些在日记账和分类账中未能记录或记录不全的经济业务进行补充登记的账簿，各单位必须设置。',False,'前半句说明用途正确，错误在各单位必须设置。备查账根据业务管理需要设置。'),
 ('T7-8','三栏式账簿是指具有日期、摘要、金额三个栏目格式的账簿。',False,'三栏指借方、贷方、余额三个主要金额栏，不是日期、摘要、金额。'),
 ('T7-10','多栏式明细分类账一般适用于债权、债务结算的明细分类账。',False,'债权债务通常适合三栏式，多栏式适合管理费用、生产成本等按项目进一步分析。'),
 ('T7-15','为了满足内部牵制原则，实行钱账分管，通常由出纳人员根据收付款凭证进行现金收支，然后，将收付款后的现金收款凭证和付款凭证交给会计人员，由会计人员登记三栏式现金日记账。',False,'现金日记账通常由出纳登记。钱账分管不是说出纳完全不记账；总账与相关会计工作按职责由其他会计人员承担。'),
 ('T7-16','登记账簿必须用蓝、黑墨水书写，不得使用圆珠笔、铅笔书写，更不得用红色墨水书写。',False,'错误在绝对禁止红墨水。规定的红字冲账、登记某些减少数等可以用红色墨水。'),
 ('T7-25','某会计人员在填制记账凭证时，误将9 800元记为8 900元，并已登记入账。月终结账前发现错误，更正时应采用划线更正法。',False,'凭证本身就有错并已入账，不是只把账簿抄错。若科目方向均正确，少记9800－8900＝900元，应蓝字补记。原题未明示科目方向，补记结论以二者正确为条件，但不能选划线法。'),
 ('T7-26','新的会计年度开始时，必须更换全部账簿，不得只更换总账和现金日记账、银行存款日记账。',False,'不能说全部更换。总账、日记账及多数明细账通常每年更换，固定资产卡片等可以连续使用。')]: q(c7,code,'判断',stem,[],correct,ex,'账簿与更正')
q(c7,'S7-3','单选','账簿按（　）的不同，可分为序时账簿、分类账簿、备查账簿。',['用途','外表形式','格式','启用时间'],0,'按用途分类。外表形式是订本、活页、卡片；账页格式是三栏、多栏、数量金额等。','账簿分类')
q(c7,'S7-4','单选','现金日记账和银行存款日记账必须采用（　）账簿。',['活页式','订本式','备查','卡片式'],1,'按本章手工账簿情境采用订本式，以便保持连续、完整，减少抽换和散失。','账簿分类')
q(c7,'S7-6','单选','企业从银行提取现金时，登记现金日记账的依据是（　）。',['现金收款凭证','现金付款凭证','银行存款收款凭证','银行存款付款凭证'],3,'现金与银行划转只编付款凭证，提现时银行存款减少，编银行存款付款凭证，并据以登记现金收入，避免重复。','登记依据')
q(c7,'S7-8','单选','下列明细账中，不宜采用三栏式账页格式的是（　）。',['应收账款明细账','应付账款明细账','管理费用明细账','短期借款明细账'],2,'管理费用需要按办公费、差旅费等分项，通常多栏式。其余往来或借款主要记录增减和余额，通常三栏式。','账页格式')
q(c7,'S7-10','单选','下列账簿中采用卡片式账簿的是（　）。',['现金日记账','固定资产','总分类账','明细分类账'],1,'B指固定资产明细核算卡片。固定资产需逐项长期记录原价、使用部门、折旧等。D过于宽泛，不是所有明细账都用卡片。','账簿分类')
q(c7,'S7-12','单选','“原材料”明细账采用的账簿格式是（　）。',['三栏式明细分类账','活页式','数量金额式明细分类账','多栏式明细分类账'],2,'材料既要记录金额，也要记录实物数量和单价，因此数量金额式。活页式是外表形式，不是本题所问账页格式。','账页格式')
q(c7,'S7-13','单选','“应收账款”所属明细账：A公司借方余额200万元，B公司借方余额400万元，C公司贷方余额300万元，D公司贷方余额100万元。不考虑其他因素，“应收账款”科目期末余额为（　）万元。',['200','600','900','1 000'],0,'借方合计200＋400＝600万元，贷方合计300＋100＝400万元；总账净借方余额600－400＝200万元。题目问总账余额，不是资产负债表项目列报额，不能把四项无方向相加。','总账余额')
q(c7,'S7-15','单选','账实核对是指账簿记录与财产物资实有数额是否相符，下列不属于账实核对的是（　）的核对。',['总分类账簿与序时账簿','银行存款日记账余额与银行对账单余额','各种实物资产明细账余额与实有数额','债权、债务明细账余额与对方单位的账面记录'],0,'A是本单位不同账簿之间的账账核对。银行对账单和往来对方记录用于核实实际款项或债权债务，属于本章账实核对。','对账')
q(c7,'S7-17','单选','结账时应通栏划双红线的情形是（　）。',['月结','季结','半年结','年结'],3,'年结时相应全年结计记录下通栏划双红线，表示年度记录结束；月结通常单红线。','结账')
q(c7,'S7-18','单选','某会计人员根据记账凭证登记入账时，误将600元填写为6 000元，而记账凭证无误。对此正确的更正方法是（　）。',['红字更正法','补充登记法','划线更正法','蓝字更正法'],2,'凭证正确，只是登账抄错，用划线更正。将错误金额整体划红线、保留原迹，在上方写600并按要求盖章，不能只去掉一个0。原照片手写A有误，不能据批注判断。','错账更正')
q(c7,'S7-19','单选','若记账凭证上的会计科目和应借应贷方向未错，但所记金额小于应记金额，并据以登记入账，对此较为恰当简便的更正方法是（　）。',['划线更正法','红字更正法','补充登记法','编制相反分录冲减'],2,'科目方向均正确、金额少记、已经入账，用蓝字按原科目方向补差额。例如应记1000记700，补300，不重复补1000。','错账更正')
q(c7,'S7-20','单选','下列各项中，可以概括总分类账与明细分类账平行登记要点的是（　）。',['依据相同、方向一致、金额相等、期间相同','方向一致、颜色相同、金额相等','同时登记、同方向登记、同金额登记','依据相同、方向一致、颜色相同'],0,'期间相同不是同一秒。金额相等是总账与相关明细账金额合计相等，例如总账1000，明细甲600乙400，不是两个明细都写1000。','平行登记')
